WITH products_by_supplier AS (SELECT supplier_id, COUNT(price) AS price_count, SUM(CASE WHEN category = 'Sports' THEN cost ELSE 0 END) AS sports_cost FROM products WHERE stock_qty < 131 GROUP BY supplier_id) SELECT s.id, s.supplier_name, s.city, pbs.price_count, pbs.sports_cost FROM suppliers s INNER JOIN products_by_supplier pbs ON s.id = pbs.supplier_id WHERE pbs.price_count >= 4 ORDER BY sports_cost DESC;
